// Lista tematów raportu. Nowy temat = nowa pozycja na liście.
// category musi pasować do kategorii w apce: zloto, gpw, usa, krypto, scamy, ogolny
const tematy = [
  {
    category: 'zloto',
    title: 'Złoto',
    prompt: 'Cena złota: aktualny poziom w USD za uncję i w PLN za gram, zmiana dzienna i tygodniowa, co napędza ruch, najnowsze prognozy banków i analityków (kto i jaki poziom).',
  },
  {
    category: 'gpw',
    title: 'GPW',
    prompt: 'Giełda Papierów Wartościowych w Warszawie: jak zamknęły się WIG20 i WIG, najważniejsze newsy o spółkach (wyniki, dywidendy, komunikaty), największe wzrosty i spadki, rekomendacje domów maklerskich.',
  },
  {
    category: 'usa',
    title: 'Rynek USA',
    prompt: 'Rynek akcji w USA: S&P 500, Nasdaq, Dow Jones, najważniejsze wydarzenia (Fed, dane makro, wyniki dużych spółek), nastroje i prognozy analityków na najbliższe dni.',
  },
  {
    category: 'krypto',
    title: 'Krypto',
    prompt: 'Kryptowaluty: kurs Bitcoina i Ethereum, zmiana 24h i 7 dni, najważniejsze wydarzenia i trendy (regulacje, ETF-y, duże przepływy), prognozy analityków.',
  },
  {
    category: 'scamy',
    title: 'Ostrzeżenia przed scamami',
    prompt: 'Nowe oszustwa inwestycyjne w Polsce z ostatnich 7 dni: ostrzeżenia CERT Polska, KNF (lista ostrzeżeń publicznych), policji, Niebezpiecznika, Sekuraka. Podaj nazwy fałszywych platform i domen, schemat działania (np. fałszywe artykuły z celebrytami, "platforma AI"), jak się chronić.',
  },
];

const dzis = new Date().toLocaleDateString('pl-PL', { timeZone: 'Europe/Warsaw' });

return tematy.map((t) => ({
  json: { ...t, title: `${t.title} — ${dzis}`, dzis },
}));
